import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ source for custom operators
custom_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// ***********************************************
// Kernel: Elementwise division by a constant
// ***********************************************
__global__ void elementwise_div_const_kernel(const float* input, const float divisor, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] / divisor;
    }
}

torch::Tensor elementwise_div_const_cuda(torch::Tensor input, float divisor) {
    auto out = torch::empty_like(input);
    int size = input.numel();

    int threads = 256;
    int blocks = (size + threads - 1) / threads;
    elementwise_div_const_kernel<<<blocks, threads>>>(input.data_ptr<float>(), divisor,
                                                     out.data_ptr<float>(), size);
    return out;
}

// ***********************************************
// Kernel: Add bias (broadcasted over batch dimension)
// Expecting x.shape = [B, C, 1, 1, 1], bias.shape = [C, 1, 1, 1]
// ***********************************************
__global__ void elementwise_add_bias_kernel(const float* input, const float* bias, float* output,
                                            int B, int C) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C;
    if (idx < total) {
        int b = idx / C;
        int c = idx % C;
        // Flatten offset for input/output
        int offset = b * C + c;  // ignoring the 1*1*1 dims
        output[offset] = input[offset] + bias[c];
    }
}

torch::Tensor elementwise_add_bias_cuda(torch::Tensor x, torch::Tensor bias) {
    // Both x and bias must be contiguous
    auto x_contig = x.contiguous();
    auto bias_contig = bias.contiguous();

    auto B = x_contig.size(0);
    auto C = x_contig.size(1);

    // Flatten out [B, C, 1, 1, 1] to [B*C]
    auto out = torch::empty_like(x_contig);

    int total = B * C;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    elementwise_add_bias_kernel<<<blocks, threads>>>(
        x_contig.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C
    );

    return out.view(x.sizes()); // reshape back
}

// ***********************************************
// Kernel: Sum over dim=1 for x.shape = [B, C, 1, 1, 1]
// Produces [B], which we can reshape to [B, 1, 1, 1] in Python
// ***********************************************
__global__ void reduce_sum_dim1_kernel(const float* input, float* output, int B, int C) {
    // Each block sums over one batch index, with a single thread to keep it simple
    int b = blockIdx.x;
    if (b < B && threadIdx.x == 0) {
        float sum_val = 0.0f;
        // offset for the batch
        int start = b * C;
        for (int c = 0; c < C; c++) {
            sum_val += input[start + c];
        }
        output[b] = sum_val;
    }
}

torch::Tensor reduce_sum_dim_cuda(torch::Tensor input) {
    // input shape: [B, C, 1, 1, 1], flattened to [B*C]
    auto in_contig = input.contiguous();
    int B = in_contig.size(0);
    int C = in_contig.size(1);
    auto out = torch::empty({B}, torch::dtype(in_contig.dtype()).device(in_contig.device()));

    dim3 blocks(B);
    dim3 threads(1);
    reduce_sum_dim1_kernel<<<blocks, threads>>>(in_contig.data_ptr<float>(),
                                                out.data_ptr<float>(), B, C);
    return out; // We'll reshape in Python
}

// Create Python bindings
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("elementwise_div_const_cuda", &elementwise_div_const_cuda, "Divide by constant (CUDA)");
    m.def("elementwise_add_bias_cuda", &elementwise_add_bias_cuda, "Add bias (CUDA)");
    m.def("reduce_sum_dim_cuda", &reduce_sum_dim_cuda, "Reduce sum over dim=1 (CUDA)");
}
"""

# Build the custom ops inline extension
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources="",
    cuda_sources=custom_ops_source,
    functions=["elementwise_div_const_cuda", "elementwise_add_bias_cuda", "reduce_sum_dim_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA operators.
    Performs:
    1) 3D convolution (PyTorch)
    2) elementwise division by a constant (custom kernel)
    3) max pooling (PyTorch)
    4) global average pooling (PyTorch)
    5) addition of bias (custom kernel)
    6) sum along dimension 1 (custom kernel)
    """
    def __init__(self, in_channels, out_channels, kernel_size, divisor, pool_size, bias_shape, sum_dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.divisor = divisor
        self.max_pool = nn.MaxPool3d(pool_size)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.sum_dim = sum_dim  # expecting sum_dim=1 for this demo

    def forward(self, x):
        # 1) Convolution
        x = self.conv(x)
        # 2) Divide by constant
        x = custom_ops.elementwise_div_const_cuda(x, float(self.divisor))
        # 3) Max pooling
        x = self.max_pool(x)
        # 4) Global average pooling
        x = self.global_avg_pool(x)
        # 5) Add bias
        x = custom_ops.elementwise_add_bias_cuda(x, self.bias)
        # 6) Sum along dim=1
        # reduce_sum_dim_cuda returns shape [B], so reshape to [B, 1, 1, 1]
        x = custom_ops.reduce_sum_dim_cuda(x).view(-1, 1, 1, 1)
        return x
